    List<StickerInfo> getInstalledStickers();
    void onStickerPackReady(String packId);
    void onInstallationFailed(int errorCode, String message);
}

// IStickerModule.aidl  
interface IStickerModule {
    void loadStickerPack(String packId);
    void encryptAndStoreSticker(inout StickerPayload payload);
}
